217. struct_with_invariants!{
218.     struct RwLock<T> {
219.         inst: Tracked<DistRwLock::Instance<T>>,
220.         exc_locked: AtomicBool<_, DistRwLock::exc_locked<T>, _>,
221.         ref_counts: Vec<AtomicU64<_, DistRwLock::ref_counts<T>, _>>,
222.     }
223. 
224.     spec fn wf(&self) -> bool {
225. 
226.         predicate {
227.             &&& self.inst@.rc_width() == self.ref_counts@.len()
228. 
229.             &&& forall |i: int| (0 <= i && i < self.ref_counts@.len()) ==>
230.                 #[trigger] self.ref_counts@.index(i).well_formed()
231.                 && self.ref_counts@.index(i).constant() == (self.inst, i)
232.         }
233. 
234.         invariant on exc_locked with (inst) is (b: bool, g: DistRwLock::exc_locked<T>) {
235.             g.instance_id() == inst@.id()
236.             && g.value() == b
237.         }
238. 
239.         invariant on ref_counts with (inst)
240.             forall |i: int|
241.             where (0 <= i < self.ref_counts@.len())
242.             specifically (self.ref_counts@[i])
243.             is (v: u64, g: DistRwLock::ref_counts<T>)
244.         {
245.             g.instance_id() == inst@.id()
246.             && g.key() == i
247.             && g.value() == v as int
248.         }
249.     }
250. }
251. 
252. impl<T> RwLock<T> {
253.     #[verifier::spinoff_prover]
254.     fn new(rc_width: usize, t: T) -> (s: Self)
255.         requires
256.             0 < rc_width,
257.         ensures
258.             s.wf(),
259.     {
260.         let tracked inst;
261.         let tracked exc_locked_token;
262.         let tracked mut ref_counts_tokens;
263.         proof {
264.             let tracked (
265.                 Tracked(inst0),
266.                 Tracked(exc_locked_token0),
267.                 Tracked(ref_counts_tokens0),
268.                 _,
269.                 _,
270.                 _,
271.                 _,
272.             ) = DistRwLock::Instance::initialize(rc_width as int, t, Option::Some(t));
273.             inst = inst0;
274.             exc_locked_token = exc_locked_token0;
275.             ref_counts_tokens = ref_counts_tokens0;
276.         }
277.         let tracked_inst: Tracked<DistRwLock::Instance<T>> = Tracked(inst.clone());
278.         let exc_locked_atomic = AtomicBool::new(
279.             Ghost(tracked_inst),
280.             false,
281.             Tracked(exc_locked_token),
282.         );
283.         let mut v: Vec<AtomicU64<(Tracked<DistRwLock::Instance<T>>, int), DistRwLock::ref_counts<T>, _>> = Vec::new();
284.         let mut i: usize = 0;
285.         assert forall|j: int|
286.             i <= j && j < rc_width implies #[trigger] ref_counts_tokens.dom().contains(j)
287.               && equal(ref_counts_tokens.index(j), 0)
288.         by {
289.             assert(ref_counts_tokens.dom().contains(j));
290.             assert(equal(ref_counts_tokens.index(j), 0));
291.         }
292.         assert(forall|j: int|
293.             #![trigger( ref_counts_tokens.dom().contains(j) )]
294.             #![trigger( ref_counts_tokens.index(j) )]
295.             i <= j && j < rc_width ==> (ref_counts_tokens.dom().contains(j)
296.               && equal(ref_counts_tokens.index(j), 0)));
297.         while i < rc_width
298.             invariant
299.                 i <= rc_width,
300.                 v@.len() == i as int,
301.                 forall|j: int|
302.                     0 <= j && j < i ==> #[trigger] v@.index(j).well_formed()
303.                       && equal(v@.index(j).constant(), (tracked_inst, j)),
304.                 tracked_inst@ == inst,
305.                 ref_counts_tokens.instance_id() == inst.id(),
306.                 forall|j: int|
307.                     #![trigger( ref_counts_tokens.dom().contains(j) )]
308.                     #![trigger( ref_counts_tokens.index(j) )]
309.                     i <= j && j < rc_width ==> (ref_counts_tokens.dom().contains(j)
310.                       && equal(ref_counts_tokens.index(j), 0)),
311.         {
312.             assert(ref_counts_tokens.dom().contains(i as int));
313.             let tracked ref_count_token = ref_counts_tokens.remove(i as int);
314.             let rc_atomic = AtomicU64::new(
315.                 Ghost((tracked_inst, i as int)),
316.                 0,
317.                 Tracked(ref_count_token),
318.             );
319.             v.push(rc_atomic);
320.             i = i + 1;
321.             assert forall|j: int|
322.                 i <= j && j < rc_width implies #[trigger] ref_counts_tokens.dom().contains(j)
323.                 && equal(ref_counts_tokens.index(j), 0)
324.             by {
325.                 assert(ref_counts_tokens.dom().contains(j));
326.                 assert(equal(ref_counts_tokens.index(j), 0));
327.             }
328.         }
329.         let s = RwLock { inst: Tracked(inst), exc_locked: exc_locked_atomic, ref_counts: v };
330.         assert(s.inst@.rc_width() == s.ref_counts@.len());
331.         s
332.     }
333. }
334. 
335. } 
